import{_ as o,o as t,c as e,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"application.yml中配置使用方式","description":"","frontmatter":{"title":"application.yml中配置使用方式","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/C-配置与整合/application.yml中配置使用方式/application.yml中配置使用方式.md","filePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/C-配置与整合/application.yml中配置使用方式/application.yml中配置使用方式.md"}'),i={name:"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/C-配置与整合/application.yml中配置使用方式/application.yml中配置使用方式.md"};function p(n,a,l,s,m,c){return t(),e("div",null,[...a[0]||(a[0]=[r('<div><ol><li>使用 @Value 注解 你可以使用 @Value 注解将 application.yaml 文件中的配置值注入到你的Bean属性中。 例如：</li></ol><h1 id="application-yaml" tabindex="-1">application.yaml <a class="header-anchor" href="#application-yaml" aria-label="Permalink to &quot;application.yaml&quot;">​</a></h1><p>app: message: Hello World ￼import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; @Component public class AppConfig { @Value(&quot;${app.message}&quot;) private String message; public String getMessage() { return message; } }</p><ol start="2"><li>使用 @ConfigurationProperties 注解 如果你有一组配置属性，你可以创建一个Java类，并使用 @ConfigurationProperties 注解将 application.yaml 文件中的配置值绑定到该类的属性上。 例如：</li></ol><h1 id="application-yaml-1" tabindex="-1">application.yaml <a class="header-anchor" href="#application-yaml-1" aria-label="Permalink to &quot;application.yaml&quot;">​</a></h1><p>app: name: My Application version: 1.0 ￼import org.springframework.boot.context.properties.ConfigurationProperties; import org.springframework.stereotype.Component; @Component @ConfigurationProperties(prefix = &quot;app&quot;) public class AppConfig { private String name; private String version; // Getters and Setters }</p><ol start="3"><li>使用 Environment 对象 你还可以注入 Environment 对象，并使用它来访问 application.yaml 文件中的配置值。 例如：</li></ol><h1 id="application-yaml-2" tabindex="-1">application.yaml <a class="header-anchor" href="#application-yaml-2" aria-label="Permalink to &quot;application.yaml&quot;">​</a></h1><p>app: message: Hello World ￼import org.springframework.beans.factory.annotation.Autowired; import org.springframework.core.env.Environment; import org.springframework.stereotype.Component; @Component public class AppConfig { @Autowired private Environment env; public String getMessage() { return env.getProperty(&quot;app.message&quot;); } }</p><ol start="4"><li>使用 @PropertySource 和 PropertyResolver 这种方法允许你将一个 @PropertySource 注解与一个 PropertyResolver 或 Environment 对象结合使用来访问 application.yaml 文件中的配置值。 例如：</li></ol><h1 id="application-yaml-3" tabindex="-1">application.yaml <a class="header-anchor" href="#application-yaml-3" aria-label="Permalink to &quot;application.yaml&quot;">​</a></h1><p>app: message: Hello World ￼import org.springframework.beans.factory.annotation.Autowired; import org.springframework.context.annotation.Configuration; import org.springframework.context.annotation.PropertySource; import org.springframework.core.env.Environment; @Configuration @PropertySource(&quot;classpath:application.yaml&quot;) public class AppConfig { @Autowired private Environment env; public String getMessage() { return env.getProperty(&quot;app.message&quot;); } }</p><p>请注意， @PropertySource 通常用于加载 .properties 文件。为了处理 .yaml 文件，你可能需要额外配置或使用上述其他方法。</p><p>这些方法可以帮助你根据项目的需求选择最适合的方式来访问和使用 application.yaml 文件中的配置值。</p></div>',1)])])}const y=o(i,[["render",p]]);export{u as __pageData,y as default};
